(37000, 63759, 1965344, '志翔', 16015, 1642328850, '好像是的...', 0, '111.2.209.20', 46296, 0),
(37001, 64841, 1965454, '流浪狗', 16161, 1642335041, '好耶！！！！！', 0, '10.186.177.36', 34894, 0),
(37002, 66882, 1964250, '田田子', 15950, 1642342836, '2.3组感觉意思没表达出来。第二组如果画面只有小孩的话可以选择更有张力的，如果要强调延续的话可以增加长辈的元素', 0, '125.113.19.54', 53606, 0),
